mapper.select:
SELECT id, user_id, question_id, category_id, wrong_count,
       last_wrong_answer, master_status, last_wrong_at, created_at, updated_at
FROM wrong_question
WHERE user_id = #{userId}

    AND category_id = #{categoryId}

ORDER BY last_wrong_at DESC

mapper.delete:
DELETE FROM wrong_question
WHERE user_id = #{userId}
  AND question_id = #{questionId}

mapper.select:
SELECT COUNT(*)
FROM wrong_question
WHERE user_id = #{userId}
